"use strict";(globalThis.webpackChunkgrc||=[]).push([[13114],{24706(e){e.exports=JSON.parse('{"citeKey":"chen2008algorithmsystem","slug":"chen-2008-algorithm-system-cffa","title":"Algorithm-System Scalability of Heterogeneous Computing","authors":["Y. Chen","X.-H. Sun","M. Wu"],"venue":"Journal of Parallel and Distributed Computing, vol. 68, pp. 1403-1412","type":"Journal","entryType":"article","date":"January, 2008","year":2008,"era":"iit","month":1,"doi":"10.1016/j.jpdc.2008.06.007","abstract":"Scalability is a key factor of the design of distributed systems and parallel algorithms and machines. However, conventional scalabilities are designed for homogeneous parallel processing. There is no suitable and commonly accepted definition of scalability metric for heterogeneous systems. Isospeed scalability is a well-defined metric for homogeneous computing. This study extends the isospeed scalability metric to general heterogeneous computing systems. The proposed isospeed-efficiency model is suitable for both homogeneous and heterogeneous computing. Through theoretical analyses, we derive methodologies of scalability measurement and prediction for heterogeneous systems. Experimental results have verified the analytical results and confirmed that the proposed isospeed-efficiency scalability works well in both homogeneous and heterogeneous environments.","hasAbstract":true,"lede":"The proposed isospeed-efficiency model is suitable for both homogeneous and heterogeneous computing.","links":{"pdf":"https://grc.iit.edu/papers/2008/chen-2008-algorithm-system-cffa.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);